"""Immutable live-packet record.

A packet is created exactly once per enqueue attempt.  Every field is fixed at
creation so checkpoint snapshots can share packet objects safely.
"""


class Pkt:
    __slots__ = ("pktid", "flowid", "length", "flow_size", "rank", "ordinal",
                 "bank", "base")

    def __init__(self, pktid, flowid, length, flow_size, rank=0, ordinal=0,
                 bank=0, base=0):
        self.pktid = pktid
        self.flowid = flowid
        self.length = length
        self.flow_size = flow_size
        self.rank = rank
        self.ordinal = ordinal        # immutable tie ordinal: event index
        self.bank = bank              # dispatch bank; never relocated
        self.base = base              # lag reference count at admission

    def lag(self, served_above):
        """Live lag: higher-rank services observed while resident."""
        return served_above - self.base
