"""Rank policies for the branchable experiment engine.

Every policy assigns a rank on *every* enqueue attempt (rejected attempts
included).  Mutable policy state is captured by ``snapshot``/``restore`` so
checkpoint branches stay isolated.
"""
from treap import insert as _insert, find as _find, items as _items


class SchedulingAlgorithm:
    def rank(self, pkt):
        raise NotImplementedError

    def feedback(self, rank):
        """Post-service update attached to a successful pop."""

    def snapshot(self):
        return None

    def restore(self, snap):
        pass

    def certificate(self):
        raise NotImplementedError


class FifoAlgorithm(SchedulingAlgorithm):
    """Increment a counter and use its new value as the rank."""

    def __init__(self):
        self.time = 0

    def rank(self, pkt):
        self.time += 1
        return self.time

    def snapshot(self):
        return self.time

    def restore(self, snap):
        self.time = snap

    def certificate(self):
        return {"kind": "fifo", "time": self.time}


class SpAlgorithm(SchedulingAlgorithm):
    """Configured strict-priority level per flow."""

    def __init__(self, levels):
        self.levels = dict(levels)

    def rank(self, pkt):
        return self.levels[pkt.flowid]

    def certificate(self):
        return {"kind": "sp",
                "levels": [[f, self.levels[f]] for f in sorted(self.levels)]}


class pFabricAlgorithm(SchedulingAlgorithm):
    """Shortest-flow-first: rank is the supplied flow size."""

    def __init__(self):
        pass

    def rank(self, pkt):
        return pkt.flow_size

    def certificate(self):
        return {"kind": "sff"}


class WFQAlgorithm(SchedulingAlgorithm):
    """Quantized finish tags: F[f] = max(F[f], V) + ceil(len*2^20 / w[f])."""

    def __init__(self, weights):
        self.virtual_time = 0
        self.weights = None   # flow -> weight
        self.finish = None    # flow -> finish tag
        for flow, weight in weights:
            self.weights = _insert(self.weights, flow, weight)
            self.finish = _insert(self.finish, flow, 0)

    def rank(self, pkt):
        weight = _find(self.weights, pkt.flowid)
        tag = _find(self.finish, pkt.flowid)
        floor = self.virtual_time
        if tag > floor:
            floor = tag
        tag = floor + (pkt.length * 1048576 + weight - 1) // weight
        self.finish = _insert(self.finish, pkt.flowid, tag)
        return tag

    def feedback(self, rank):
        if rank > self.virtual_time:
            self.virtual_time = rank

    def set_weight(self, flow, weight):
        self.weights = _insert(self.weights, flow, weight)

    def snapshot(self):
        return (self.virtual_time, self.finish, self.weights)

    def restore(self, snap):
        self.virtual_time, self.finish, self.weights = snap

    def certificate(self):
        return {"kind": "wfq",
                "virtual_time": self.virtual_time,
                "weights": [[f, w] for f, w in _items(self.weights)],
                "finish": [[f, v] for f, v in _items(self.finish)]}


def build_policy(spec):
    kind = spec["kind"]
    if kind == "fifo":
        return FifoAlgorithm()
    if kind == "sp":
        return SpAlgorithm(spec["levels"])
    if kind == "sff":
        return pFabricAlgorithm()
    if kind == "wfq":
        return WFQAlgorithm(spec["weights"])
    raise ValueError("unknown policy")
